/// Translate errors generated by our native preview channels while retaining
/// unknown platform details for diagnosis.
String localizedNativePreviewError(BuildContext context, Object error) {
  final code = error is SystemPreviewException
      ? error.code
      : error is PdfTextException
          ? error.code
          : null;
  final language = Localizations.maybeLocaleOf(context)?.languageCode ?? 'en';
  return (_messages[language] ?? _messages['en']!)[code] ?? error.toString();
}

